const error = $json;

const execution = error.execution || {};
const workflow  = error.workflow  || {};

// Try to find tenant_id anywhere in the failed execution's run data
let tenant_id = 'b2b-saas-demo';
try {
  const runData =
    execution.data?.resultData?.runData ||
    execution.data?.runData ||
    {};

  for (const nodeName of Object.keys(runData)) {
    const runs = runData[nodeName];
    if (!Array.isArray(runs)) continue;

    for (const run of runs) {
      const items = run?.data?.main?.[0] || [];
      for (const item of items) {
        const j = item?.json || {};
        if (j.tenant_id) { tenant_id = j.tenant_id; break; }
        if (j.body?.tenant_id) { tenant_id = j.body.tenant_id; break; }
      }
      if (tenant_id !== 'b2b-saas-demo') break;
    }
    if (tenant_id !== 'b2b-saas-demo') break;
  }
} catch (_) {
  // fall back to default tenant
}

return [{
  json: {
    tenant_id,
    status: 'failed',
    workflow_name: workflow.name || 'Unknown workflow',
    execution_id: execution.id ? String(execution.id) : '',
    execution_url: execution.url || '',
    failed_node: execution.lastNodeExecuted || 'Unknown node',
    error_message:
      execution.error?.message ||
      error.error?.message ||
      'Unknown error',
    error_stack:
      execution.error?.stack ||
      error.error?.stack ||
      null,
    occurred_at: new Date().toISOString()
  }
}];

const data = $json;

return {
  json: {
    ...data,

    stage: data.failed_node || 'unknown',

    severity: 'error',

    error_type: 'workflow_failure'
  }
};
